inline const char* resolveMarioSingleClip(const char* logical){assetCheck(logical!=nullptr,"Missing Mario animation name");for(const auto& entry:singleAnimeTable){if(!*entry.mParent.mAnimationName)break;if(MR::isEqualStringCase(logical,entry.mParent.mAnimationName))return entry.mFileName;}return nullptr;}
inline const char* resolveMarioGameSingleClip(const std::string& logical){auto utf8=animationNameFromGame(logical);return resolveMarioSingleClip(utf8.c_str());}
inline void marioAnimationNameTests(){size_t names=0;for(const auto& entry:singleAnimeTable){if(!*entry.mParent.mAnimationName)break;std::string original=entry.mParent.mAnimationName;auto game=animationNameToGame(original);assetCheck(animationNameFromGame(game)==original,"Mario animation name encoding roundtrip failed");auto utf8Clip=resolveMarioSingleClip(original.c_str()),gameClip=resolveMarioGameSingleClip(game);assetCheck(utf8Clip&&gameClip&&std::strcmp(utf8Clip,gameClip)==0,"Encoded Mario single clip lookup diverged");++names;}assetCheck(names>0,"No Mario animation names checked");for(const auto& input:std::vector<std::pair<std::string,UINT>>{{std::string(1,char(0xff)),CP_UTF8},{std::string(1,char(0x81)),932},{std::string("a\0b",3),CP_UTF8}}){bool rejected=false;try{convertAnimationName(input.first,input.second,CP_UTF8);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Malformed animation name accepted");}assetCheck(resolveMarioGameSingleClip("missing-animation")==nullptr,"Unknown game animation name resolved");}
inline size_t verifyMarioSingleClips(const Rarc& archive){size_t groups=0;for(const auto& entry:singleAnimeTable){if(!*entry.mParent.mAnimationName)break;assetCheck(resolveMarioSingleClip(entry.mParent.mAnimationName)!=nullptr,"Original Mario single animation name lookup failed");std::string path;for(const auto& resource:archive.files){auto file=std::filesystem::path(resource.path);if(file.extension()==".bck"&&MR::isEqualStringCase(file.stem().string().c_str(),entry.mFileName)){assetCheck(path.empty(),"Ambiguous Mario clip basename");path=resource.path;}}if(path.empty())continue;auto bytes=archive.readFile(path);auto animation=decodeBck(BinaryView(bytes));AnimationClock clock(animation);for(int i=0;i<120;++i)clock.tick();++groups;}assetCheck(groups>0,"No original Mario single-group clips resolved");return groups;}


struct NativeMarioGroupTrack { std::string clip; float weight; };
inline std::vector<NativeMarioGroupTrack> resolveMarioGroup(const char* logical){
 assetCheck(logical!=nullptr,"Missing Mario group name");
 if(auto single=resolveMarioSingleClip(logical))return {{single,1}};
 std::vector<NativeMarioGroupTrack> result;
 auto search=[&](const auto& table){for(const auto& group:table){if(!*group.mParent.mAnimationName)break;if(MR::isEqualStringCase(logical,group.mParent.mAnimationName)){for(const auto& track:group.mEntries){assetCheck(track.mFileName&&*track.mFileName&&std::isfinite(track._4)&&track._4>=0,"Invalid original Mario group track");result.push_back({track.mFileName,track._4});}return true;}}return false;};
 if(search(doubleAnimeTable)||search(tripleAnimeTable)||search(quadAnimeTable))return result;
 return {};
}
inline std::vector<NativeMarioGroupTrack> resolveMarioGameGroup(const std::string& logical){auto utf8=animationNameFromGame(logical);return resolveMarioGroup(utf8.c_str());}
inline std::string marioGroupClipPath(const Rarc& archive,const std::string& clip){std::string result;for(const auto& resource:archive.files){auto file=std::filesystem::path(resource.path);if(file.extension()==".bck"&&MR::isEqualStringCase(file.stem().string().c_str(),clip.c_str())){assetCheck(result.empty(),"Ambiguous Mario group clip");result=resource.path;}}assetCheck(!result.empty(),("Missing Mario group clip: "+clip).c_str());return result;}
inline ModelRig marioGroupPose(const Rarc& archive,const ModelRig& rig,const std::vector<NativeMarioGroupTrack>& group,float frame){assetCheck(!group.empty(),"Unknown Mario group");std::vector<ModelRig> poses;std::vector<float> weights;for(const auto& track:group){auto bytes=archive.readFile(marioGroupClipPath(archive,track.clip));auto clip=decodeBck(BinaryView(bytes));poses.push_back(clip.pose(rig,frame));weights.push_back(track.weight);}return blendAnimationTracks(rig,poses,weights);}
inline void marioMultiGroupTests(){size_t count=0;auto check=[&](const auto& table){for(const auto& group:table){if(!*group.mParent.mAnimationName)break;auto tracks=resolveMarioGameGroup(animationNameToGame(group.mParent.mAnimationName));assetCheck(tracks.size()==sizeof(group.mEntries)/sizeof(group.mEntries[0]),"Mario group track count mismatch");for(size_t i=0;i<tracks.size();++i)assetCheck(tracks[i].clip==group.mEntries[i].mFileName&&tracks[i].weight==group.mEntries[i]._4,"Mario group track order/weight mismatch");++count;}};check(doubleAnimeTable);check(tripleAnimeTable);check(quadAnimeTable);assetCheck(count>0&&resolveMarioGroup("missing-group").empty(),"Mario group lookup failed");}



