// Native grouped playback: each clip retains its own original J3D frame controller.
class NativeMarioClipCache {
 const Rarc& archive;std::map<std::string,std::shared_ptr<const JointAnimation>> clips;std::map<std::string,std::string> paths;
 static std::string key(std::string name){for(char& c:name)if(c>='A'&&c<='Z')c=char(c+32);return name;}
public:
 size_t decodes=0;
 explicit NativeMarioClipCache(const Rarc& source):archive(source){for(const auto& resource:archive.files){auto file=std::filesystem::path(resource.path);if(file.extension()!=".bck")continue;auto name=key(file.stem().string());auto inserted=paths.emplace(name,resource.path);if(!inserted.second)inserted.first->second.clear();}}
 std::shared_ptr<const JointAnimation> getShared(const std::string& name){auto indexed=paths.find(key(name));assetCheck(indexed!=paths.end(),"Missing indexed Mario clip");assetCheck(!indexed->second.empty(),"Ambiguous indexed Mario clip");auto path=indexed->second;auto found=clips.find(path);if(found!=clips.end())return found->second;auto bytes=archive.readFile(path);auto clip=decodeBck(BinaryView(bytes));auto inserted=clips.emplace(path,std::make_shared<const JointAnimation>(std::move(clip)));++decodes;return inserted.first->second;}
 const JointAnimation& get(const std::string& name){return *getShared(name);}
};
class NativeMarioGroupPlayer {
 mutable std::optional<ModelRig> sampledPose;mutable size_t sampledTracks=0;std::shared_ptr<NativeMarioClipCache> clipCache;
 bool sampleBeforeMovement=false,hasMovementSample=false;float movementFrame=0;
 std::array<bool,4> phaseOverride{};std::array<float,4> phases{};bool sharedPhase=false;NativeAnimationInterpolation interpolation;bool originalInterpolation=false;std::unique_ptr<NativeAnimationPoseHistory> history;ModelRig base;
 std::vector<std::shared_ptr<const JointAnimation>> clips;
 std::vector<AnimationClock> clocks;
 std::vector<float> weights;
public:
 NativeMarioGroupPlayer(const Rarc& archive,const ModelRig& rig,const std::vector<NativeMarioGroupTrack>& group,std::shared_ptr<NativeMarioClipCache> cache=nullptr):clipCache(std::move(cache)),base(rig){
  assetCheck(!group.empty()&&group.size()<=4,"Invalid Mario playback group");
  for(const auto& track:group){if(clipCache)clips.push_back(clipCache->getShared(track.clip));else{auto bytes=archive.readFile(marioGroupClipPath(archive,track.clip));clips.push_back(std::make_shared<const JointAnimation>(decodeBck(BinaryView(bytes))));}assetCheck(clips.back()->joints.size()==rig.joints.size(),"Mario group joint count mismatch");clocks.emplace_back(*clips.back());weights.push_back(track.weight);}
 }
 void replaceGroup(const Rarc& archive,const std::vector<NativeMarioGroupTrack>& group,int transitionFrames=0){
  NativeMarioGroupPlayer next(archive,base,group,clipCache);next.rawPose();auto validationClocks=next.clocks;for(auto& clock:validationClocks)clock.tick();auto captured=pose();auto nextHistory=std::make_unique<NativeAnimationPoseHistory>(captured);nextHistory->begin(0);NativeAnimationInterpolation nextInterpolation;nextInterpolation.change(transitionFrames,next.clocks[0].rate,next.clocks[0].mode);
  clips=std::move(next.clips);clocks=std::move(next.clocks);weights=std::move(next.weights);sampledPose.reset();phaseOverride={};phases={};hasMovementSample=false;history=std::move(nextHistory);interpolation=nextInterpolation;originalInterpolation=true;
 }
 void setWeights(const std::vector<float>& next){assetCheck(next.size()==weights.size(),"Mario group weight count mismatch");float total=0;for(float weight:next){assetCheck(std::isfinite(weight)&&weight>=0,"Invalid Mario runtime weight");total+=weight;}assetCheck(std::isfinite(total),"Mario runtime weights overflow");if(weights!=next){weights=next;sampledPose.reset();}}
 // MarioAnimator::targetWeight arithmetic with explicit native context inputs.
 void approachWeights(const std::vector<float>& targets,float rate,bool swimming=false,float swimRate=0,bool alternateState=false){
  assetCheck(targets.size()==weights.size(),"Mario target weight count mismatch");
  float effective=swimming?swimRate:(alternateState?.5f:rate);
  assetCheck(std::isfinite(effective)&&effective>=0&&effective<=1,"Invalid Mario weight approach rate");
  auto next=weights;for(size_t i=0;i<next.size();++i){assetCheck(std::isfinite(targets[i])&&targets[i]>=0,"Invalid Mario target weight");next[i]=next[i]*(1.f-effective)+targets[i]*effective;}setWeights(next);
 }
 // MarioAnimator::setHipSlidingTilt directional target calculation.
 void setHipSlidingTilt(float x,float y,float rate){
  assetCheck(weights.size()==4&&std::isfinite(x)&&std::isfinite(y)&&std::abs(x)<=1&&std::abs(y)<=1,"Invalid Mario sliding tilt input/group");
  const float maximum=1.414213f;std::vector<float> targets;
  for(auto direction:std::array<std::array<float,2>,4>{{{0,1},{0,-1},{-1,0},{1,0}}}){float dx=direction[0]-x,dy=direction[1]-y;float distance=std::sqrt(dx*dx+dy*dy);float weight=distance>=maximum?0:(maximum-distance)/maximum;targets.push_back(weight*weight);}
  approachWeights(targets,rate);
 }
 void setTrackPhase(size_t track,float phase){assetCheck(track<clips.size()&&std::isfinite(phase)&&phase>=0&&phase<=1,"Invalid Mario track phase override");phases[track]=phase;phaseOverride[track]=true;sampledPose.reset();}
 void clearTrackPhase(size_t track){assetCheck(track<clips.size(),"Invalid Mario track phase index");phaseOverride[track]=false;sampledPose.reset();}
 void useFrameBeforeMovement(bool enabled=true){sampleBeforeMovement=enabled;hasMovementSample=false;sampledPose.reset();}
 void useOriginalSharedPhase(bool enabled=true){sharedPhase=enabled;sampledPose.reset();}
 float sampleFrame(size_t track)const{assetCheck(track<clips.size(),"Invalid Mario sample track");if(phaseOverride[track])return phases[track]*clips[track]->duration;if(!sharedPhase)return clocks[track].frame;float frame=(clocks[0].state&1)?clocks[0].end:(sampleBeforeMovement&&hasMovementSample?movementFrame:clocks[0].frame);float maximum=clips[0]->duration==0?1:clips[0]->duration;return frame/maximum*clips[track]->duration;}
 size_t mainTranslationTrack()const{size_t index=0;float threshold=weights[0]+.01f;for(size_t i=1;i<weights.size();++i)if(weights[i]>threshold){index=i;threshold=weights[i]+.01f;}return index;}
 std::array<float,3> mainAnimationTranslation(size_t joint)const{assetCheck(joint<base.joints.size(),"Invalid Mario translation joint");auto index=mainTranslationTrack();auto sampled=clips[index]->pose(base,sampleFrame(index));return sampled.joints[joint].translation;}
 const std::vector<float>& trackWeights()const{return weights;}
 // Explicit native fallback restart; original Xanime default selection remains pending.
 void restartPlayback(){auto next=clocks;for(auto& clock:next){clock.frame=clock.start;clock.state=0;if(clock.rate==0)clock.rate=1;}clocks=std::move(next);hasMovementSample=false;sampledPose.reset();}
 // Explicit per-track controls; full XanimePlayer group control propagation remains pending.
 std::vector<int> configureTracks(const std::vector<BckCtrlData>& controls){
  assetCheck(controls.size()==clocks.size(),"Mario group control count mismatch");auto next=clocks;std::vector<int> interpolation;
  for(size_t i=0;i<next.size();++i)interpolation.push_back(applyBckSettings(next[i],controls[i]));clocks=std::move(next);sampledPose.reset();return interpolation;
 }
 void beginOriginalPoseTransition(int frames){auto next=interpolation;next.change(frames,clocks[0].rate,clocks[0].mode);if(!history)history=std::make_unique<NativeAnimationPoseHistory>(rawPose());history->begin(0);interpolation=next;originalInterpolation=true;}
 void beginPoseTransition(unsigned ticks,float smoothing=1){originalInterpolation=false;if(!history)history=std::make_unique<NativeAnimationPoseHistory>(rawPose());history->begin(ticks,smoothing);}
 void tick(){float before=clocks[0].frame;auto next=clocks;for(auto& clock:next)if((clock.state&1)==0)clock.tick();clocks=std::move(next);sampledPose.reset();movementFrame=before;hasMovementSample=true;if(history){if(originalInterpolation){interpolation.update(clocks[0].rate,clocks[0].mode);history->advanceRatio(rawPose(),interpolation.ratio);}else history->advance(rawPose());}}
 ModelRig pose()const{return history?history->pose():rawPose();}
 size_t poseSampleCount()const{return sampledTracks;}
 ModelRig rawPose()const{if(sampledPose)return *sampledPose;std::vector<ModelRig> poses;std::vector<float> active;for(size_t i=0;i<clips.size();++i){assetCheck(std::isfinite(weights[i])&&weights[i]>=0,"Invalid Mario sampled track weight");if(weights[i]==0)continue;poses.push_back(clips[i]->pose(base,sampleFrame(i)));active.push_back(weights[i]);++sampledTracks;}sampledPose=blendAnimationTracks(base,poses,active);return *sampledPose;}
 // Original XanimePlayer::isTerminate checks controller state bit 1.
 NativeMarioWalkCadence applyWalkCadence(const NativeMarioWalkCadenceContext& context){auto result=nativeMarioWalkCadence(context);changeMainSpeed(result.rate);return result;}
 void changeMainSpeed(float rate){assetCheck(std::isfinite(rate)&&std::abs(rate)<=4096,"Invalid Mario main playback speed");clocks[0].rate=rate;sampledPose.reset();}
 bool isTerminated()const{return (clocks[0].state&1)!=0;}
 bool isTrackTerminated(size_t track)const{assetCheck(track<clocks.size(),"Invalid Mario termination track");return (clocks[track].state&1)!=0;}
 const std::vector<AnimationClock>& trackClocks()const{return clocks;}
};
